    h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_HSD_Archive[0]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_HSD_Archive[0]))), D_HSD_Archive);  h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_HSD_Archive[1]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_HSD_Archive[1]))), D_HSD_Archive);  WH.push(h);
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(t::grDatFiles_8049EE10) as *const u8, core::mem::size_of_val(&*addr_of!(t::grDatFiles_8049EE10))), D_st0);
